import{_ as l,D as o,o as r,c as i,j as e,a,I as d,w as n,am as s}from"./chunks/framework.DXw8qDd0.js";const _=JSON.parse('{"title":"Codex vs Claude Code 功能对比","description":"","frontmatter":{"title":"Codex vs Claude Code 功能对比","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex vs Claude Code 功能对比.md","filePath":"笔记/Codex/Codex vs Claude Code 功能对比.md"}'),h={name:"笔记/Codex/Codex vs Claude Code 功能对比.md"},u=s('<h1 id="codex-vs-claude-code-功能对比与优势分析" tabindex="-1">Codex vs Claude Code：功能对比与优势分析 <a class="header-anchor" href="#codex-vs-claude-code-功能对比与优势分析" aria-label="Permalink to &quot;Codex vs Claude Code：功能对比与优势分析&quot;">​</a></h1><blockquote><p>对比 Codex（Codex Desktop App）和 Claude Code（Anthropic CLI Agent）的核心能力差异。</p></blockquote><hr><h2 id="一、codex-的三大核心优势-你已经发现的" tabindex="-1">一、Codex 的三大核心优势（你已经发现的） <a class="header-anchor" href="#一、codex-的三大核心优势-你已经发现的" aria-label="Permalink to &quot;一、Codex 的三大核心优势（你已经发现的）&quot;">​</a></h2><h3 id="_1-插件系统-plugins" tabindex="-1">1. 插件系统（Plugins） <a class="header-anchor" href="#_1-插件系统-plugins" aria-label="Permalink to &quot;1. 插件系统（Plugins）&quot;">​</a></h3><ul><li>Codex 有插件生态，比如 GitHub、Chrome、Documents、Presentations、Spreadsheets 等插件，开箱即用</li><li>Claude Code 没有插件市场，需要自己手动配置 MCP Server</li></ul><h3 id="_2-技能系统-skills" tabindex="-1">2. 技能系统（Skills） <a class="header-anchor" href="#_2-技能系统-skills" aria-label="Permalink to &quot;2. 技能系统（Skills）&quot;">​</a></h3><ul><li>Codex 支持 SKILL.md，可以封装特定领域知识和工作流（比如做卡片、生成视频、操作飞书等）</li><li>Claude Code 没有原生的技能系统，需要通过 System Prompt 手动注入</li></ul><h3 id="_3-记忆系统-memory" tabindex="-1">3. 记忆系统（Memory） <a class="header-anchor" href="#_3-记忆系统-memory" aria-label="Permalink to &quot;3. 记忆系统（Memory）&quot;">​</a></h3><ul><li>Codex 有 AGENTS.md、持久化的记忆文件，跨会话保持上下文</li><li>Claude Code 依赖项目的 CLAUDE.md，但没有 Codex 这么结构化的多层记忆体系</li></ul><hr><h2 id="二、你可能没想到的额外优势" tabindex="-1">二、你可能没想到的额外优势 <a class="header-anchor" href="#二、你可能没想到的额外优势" aria-label="Permalink to &quot;二、你可能没想到的额外优势&quot;">​</a></h2><h3 id="_4-图形界面-桌面端" tabindex="-1">4. 图形界面（桌面端） <a class="header-anchor" href="#_4-图形界面-桌面端" aria-label="Permalink to &quot;4. 图形界面（桌面端）&quot;">​</a></h3><ul><li>Codex 有<strong>桌面应用</strong>，可以直接看到输出、终端、文件预览、图片展示</li><li>Claude Code 是纯终端 CLI，所有输出都是文本</li></ul><h3 id="_5-浏览器自动化内置" tabindex="-1">5. 浏览器自动化内置 <a class="header-anchor" href="#_5-浏览器自动化内置" aria-label="Permalink to &quot;5. 浏览器自动化内置&quot;">​</a></h3><ul><li>Codex 内置了 <strong>Browser 插件</strong>（In-App Browser）和 <strong>Chrome 插件</strong>，可以直接操控浏览器</li><li>Claude Code 没有浏览器能力，需要额外配置 Playwright MCP 等</li></ul><h3 id="_6-多-agent-协作" tabindex="-1">6. 多 Agent 协作 <a class="header-anchor" href="#_6-多-agent-协作" aria-label="Permalink to &quot;6. 多 Agent 协作&quot;">​</a></h3><ul><li>Codex 支持 spawn_agent <strong>子 Agent 并行协作</strong>，可以把任务分发给多个子 Agent 同时执行</li><li>Claude Code 是单会话模式，没有内置的多 Agent 编排</li></ul><h3 id="_7-app-连接器-connectors" tabindex="-1">7. App 连接器（Connectors） <a class="header-anchor" href="#_7-app-连接器-connectors" aria-label="Permalink to &quot;7. App 连接器（Connectors）&quot;">​</a></h3><ul><li>Codex 有 App 连接器概念，可以直接连接 Slack、Teams、Gmail、Notion、Google Calendar 等第三方服务</li><li>Claude Code 需要自己搭建 MCP 集成</li></ul><h3 id="_8-自动化与定时任务-automations" tabindex="-1">8. 自动化与定时任务（Automations） <a class="header-anchor" href="#_8-自动化与定时任务-automations" aria-label="Permalink to &quot;8. 自动化与定时任务（Automations）&quot;">​</a></h3><ul><li>Codex 支持<strong>循环自动化</strong>（Cron）和<strong>心跳唤醒</strong>（Heartbeat），可以设置定时任务</li><li>Claude Code 没有这个能力</li></ul><h3 id="_9-协作模式" tabindex="-1">9. 协作模式 <a class="header-anchor" href="#_9-协作模式" aria-label="Permalink to &quot;9. 协作模式&quot;">​</a></h3><ul><li>Codex 支持 <strong>Default 模式</strong> 和 <strong>Plan 模式</strong>，可以切换工作方式</li><li>Claude Code 没有类似的模式切换机制</li></ul><h3 id="_10-工具丰富度" tabindex="-1">10. 工具丰富度 <a class="header-anchor" href="#_10-工具丰富度" aria-label="Permalink to &quot;10. 工具丰富度&quot;">​</a></h3><ul><li>Codex 开箱集成：画图（Draw.io）、PPT、Word、Excel、Node REPL、Playwright 等</li><li>Claude Code 核心是终端+文件编辑，其他都要靠 MCP 插件自己接</li></ul><hr><h2 id="三、完整对比表" tabindex="-1">三、完整对比表 <a class="header-anchor" href="#三、完整对比表" aria-label="Permalink to &quot;三、完整对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>Codex</th><th>Claude Code</th></tr></thead><tbody><tr><td>图形界面</td><td>✅ 桌面 App</td><td>❌ 纯 CLI</td></tr><tr><td>插件生态</td><td>✅ 开箱即用</td><td>❌ 需自建 MCP</td></tr><tr><td>技能系统</td><td>✅ SKILL.md</td><td>❌ 手动 Prompt</td></tr><tr><td>记忆系统</td><td>✅ 多层结构</td><td>⚠️ CLAUDE.md</td></tr><tr><td>多 Agent</td><td>✅ 子 Agent</td><td>❌ 单会话</td></tr><tr><td>浏览器操作</td><td>✅ 内置</td><td>❌ 需配置</td></tr><tr><td>定时任务</td><td>✅ 自动化</td><td>❌ 无</td></tr><tr><td>第三方连接</td><td>✅ App 连接器</td><td>❌ 需自建</td></tr></tbody></table><hr><h2 id="四、claude-code-的优势" tabindex="-1">四、Claude Code 的优势 <a class="header-anchor" href="#四、claude-code-的优势" aria-label="Permalink to &quot;四、Claude Code 的优势&quot;">​</a></h2><ul><li>轻量级、终端原生，启动快、没有 GUI 开销</li><li>Claude 模型本身的代码能力很强</li><li>适合习惯纯命令行、喜欢简洁工作流的开发者</li></ul><hr><h2 id="五、总结" tabindex="-1">五、总结 <a class="header-anchor" href="#五、总结" aria-label="Permalink to &quot;五、总结&quot;">​</a></h2><p>Codex 更像是一个<strong>全功能的工作平台</strong>，不只是写代码，还能搜索、做PPT、操作浏览器、连接各种服务，适合需要多场景协作的用户。</p><p>Claude Code 则是一个<strong>轻量级终端工具</strong>，专注代码，简洁高效。</p><hr><p><em>创建时间：2026-06-03</em><em>标签：#AI #Codex #Claude #对比分析</em></p><hr><h2 id="六、各能力的实际使用方法" tabindex="-1">六、各能力的实际使用方法 <a class="header-anchor" href="#六、各能力的实际使用方法" aria-label="Permalink to &quot;六、各能力的实际使用方法&quot;">​</a></h2><h3 id="插件系统-plugins" tabindex="-1">插件系统（Plugins） <a class="header-anchor" href="#插件系统-plugins" aria-label="Permalink to &quot;插件系统（Plugins）&quot;">​</a></h3><p>插件可以通过 <strong>@插件名</strong> 在对话中直接调用：</p><ul><li>@GitHub — 操作 PR、Issue、仓库</li><li>@Chrome — 操控你的 Chrome 浏览器</li><li>@Documents — 创建/编辑 Word 文档</li><li>@Presentations — 制作 PPT 演示文稿</li><li>@Spreadsheets — 处理 Excel 表格</li></ul><p>例如：@GitHub 帮我看看这个 PR 的状态\\</p><h3 id="技能系统-skills" tabindex="-1">技能系统（Skills） <a class="header-anchor" href="#技能系统-skills" aria-label="Permalink to &quot;技能系统（Skills）&quot;">​</a></h3><p>技能有多种触发方式：</p><ul><li><strong>斜杠命令</strong>：在对话中输入 /技能名 直接调用，例如： <ul><li>/imagegen 生成一张日落风景图</li><li>/card 把这段文字做成知识卡片</li><li>/agent-reach 搜索 xxx</li></ul></li><li><strong>自然语言触发</strong>：直接说出你的需求，Codex 会自动识别并加载对应的技能</li><li><strong>手动指定</strong>：明确说出技能名称，例如 使用 imagegen 技能生成一张图片</li></ul><p>技能本质是一套预定义的工作流和领域知识，封装在 SKILL.md 文件中。斜杠命令是最直接、最高效的调用方式，系统会立即加载对应的 SKILL.md 执行。</p><p>常用技能示例：</p><ul><li><strong>imagegen</strong> — 生成或编辑图片</li><li><strong>hyperframes</strong> — 创建视频和动画</li><li><strong>card</strong> — 生成知识卡片</li><li><strong>agent-reach</strong> — 搜索网页和社交媒体</li><li><strong>browser</strong> — 浏览器自动化操作</li><li><strong>documents</strong> — 创建和编辑 Word 文档</li></ul><h3 id="记忆系统-memory" tabindex="-1">记忆系统（Memory） <a class="header-anchor" href="#记忆系统-memory" aria-label="Permalink to &quot;记忆系统（Memory）&quot;">​</a></h3><p>Codex 的记忆通过项目根目录的 <strong>AGENTS.md</strong> 文件实现：</p><ul><li>在项目根目录放置 \\AGENTS.md\\，Codex 每次启动都会自动读取</li><li>可以在里面写：编码规范、项目说明、常用命令、注意事项等</li><li>支持<strong>多层级</strong>：每个子目录可以有自己的 \\AGENTS.md\\，越深层的越优先</li><li>效果：Codex 记住你的偏好，不用每次都重复说明</li></ul><h3 id="多-agent-协作" tabindex="-1">多 Agent 协作 <a class="header-anchor" href="#多-agent-协作" aria-label="Permalink to &quot;多 Agent 协作&quot;">​</a></h3><p>通过 <strong>spawn_agent</strong> 工具分发任务给子 Agent：</p><ul><li>Codex 会自动判断是否需要拆分任务</li><li>你也可以手动要求：\\请并行帮我分析这三个文件\\</li><li>子 Agent 在后台执行，不阻塞主流程</li></ul><h3 id="app-连接器-connectors" tabindex="-1">App 连接器（Connectors） <a class="header-anchor" href="#app-连接器-connectors" aria-label="Permalink to &quot;App 连接器（Connectors）&quot;">​</a></h3><p>连接器通过 App 名称触发，支持的服务包括：</p><ul><li><strong>Slack</strong> — 收发消息、管理频道</li><li><strong>Gmail</strong> — 读写邮件</li><li><strong>Google Calendar</strong> — 管理日程</li><li><strong>Notion</strong> — 读写文档和数据库</li><li><strong>Teams</strong> — 团队沟通</li></ul><p>首次使用时 Codex 会引导你完成授权配置。</p><h3 id="浏览器自动化" tabindex="-1">浏览器自动化 <a class="header-anchor" href="#浏览器自动化" aria-label="Permalink to &quot;浏览器自动化&quot;">​</a></h3><p>通过 <strong>@Browser</strong>（内置）或 <strong>@Chrome</strong>（你的浏览器）调用：</p><ul><li>@Browser 打开 localhost:3000\\ — 在内置浏览器中打开</li><li>@Chrome 搜索 xxx\\ — 操控你登录状态下的 Chrome</li><li>支持截图、点击、填写表单等操作</li></ul><h3 id="自动化定时任务-automations" tabindex="-1">自动化定时任务（Automations） <a class="header-anchor" href="#自动化定时任务-automations" aria-label="Permalink to &quot;自动化定时任务（Automations）&quot;">​</a></h3><p>直接用自然语言告诉 Codex 你想定时做什么：</p><ul><li>\\帮我每小时检查一次 GitHub Issue\\</li><li>\\每天早上 9 点提醒我看日报\\</li><li>Codex 会自动创建 Cron 任务或 Heartbeat 心跳任务</li></ul><hr><h2 id="更新时间-2026-06-03" tabindex="-1"><em>更新时间：2026-06-03</em> <a class="header-anchor" href="#更新时间-2026-06-03" aria-label="Permalink to &quot;*更新时间：2026-06-03*&quot;">​</a></h2>',68);function c(C,g,m,p,x,b){const t=o("VPNolebaseInlineLinkPreview");return r(),i("div",null,[u,e("blockquote",null,[e("p",null,[a("📎 "),d(t,{href:"/ocdsync/笔记/"},{default:n(()=>[a("📒 返回笔记索引")]),_:1})])])])}const q=l(h,[["render",c]]);export{_ as __pageData,q as default};
